/* Illustrative rates only. No live carrier or customs connection. */
(function(root){
// Demo rates preserve existing quotes; confirm each route with Stefanie before commercial use.
const routes={
 west:[
  {id:'regular',zh:'普船',en:'Regular ocean',kgRate:2.2,min:30,max:40,lclPerCbm:85,fclMultiplier:1},
  {id:'expedited',zh:'普快',en:'Expedited ocean',kgRate:2.8,min:23,max:30,lclPerCbm:135,fclMultiplier:1.25},
  {id:'matson',zh:'美森',en:'Matson',kgRate:3.6,min:16,max:23,lclPerCbm:190,fclMultiplier:1.5}
 ],
 east:[
  {id:'ny',zh:'直航纽约',en:'Direct to New York',kgRate:2.9,min:38,max:48,lclPerCbm:85,fclMultiplier:1},
  {id:'regular',zh:'普船转卡',en:'Regular ocean + truck',kgRate:3.2,min:35,max:45,lclPerCbm:135,fclMultiplier:1.25},
  {id:'expedited',zh:'普快转卡',en:'Expedited ocean + truck',kgRate:3.8,min:28,max:37,lclPerCbm:190,fclMultiplier:1.5},
  {id:'matson',zh:'美森转卡',en:'Matson + truck',kgRate:4.6,min:22,max:30,lclPerCbm:220,fclMultiplier:1.75}
 ]
};
function zone(zip){return Number(zip[0])<=3?'east':Number(zip[0])>=8?'west':'central'}
function valid(d){if(!['fba','awd','commercial','other'].includes(d.destination))throw Error('Select a destination type');if(!d.product?.trim()||!['Shanghai','Ningbo','Shenzhen','Qingdao','Xiamen'].includes(d.origin)||!/^\d{5}$/.test(d.zip)||!/^\d{4}-\d{2}-\d{2}$/.test(d.ready)||!Number.isFinite(Date.parse(d.ready)))throw Error('Invalid shipment');for(const k of ['weight','volume','cartons','pieces'])if(!Number.isFinite(+d[k])||+d[k]<=0)throw Error('Invalid quantity');if(!Number.isInteger(+d.pieces)||!Number.isInteger(+d.cartons))throw Error('Whole counts required');if(d.deadline&&d.deadline<d.ready)throw Error('Deadline precedes cargo ready date');}
function options(d){valid(d);return zone(d.zip)==='east'?routes.east:routes.west.map(r=>zone(d.zip)==='central'?{...r,zh:r.zh+'转卡',en:r.en+' + truck',kgRate:r.kgRate+.6,min:r.min+5,max:r.max+7}:r)}
function ecommerce(d){return options(d).map(r=>{const billed=Math.ceil(Math.max(+d.weight,+d.volume*167)),freight=Math.max(100,billed*r.kgRate);return{id:r.id,zh:r.zh,en:r.en,min:r.min,max:r.max,billed,rate:r.kgRate,total:freight,per:freight/d.pieces,rows:[['渠道运费（含尾程）','Channel freight (delivery included)',freight]],kind:'ecom'}})}
function loadPlan(d,x){const cfg=root.FreightRules;if(!cfg)throw Error('Missing freight rules');const large=+d.volume>=cfg.fullLoadThresholdCbm,auto=x.load==='AUTO',load=auto?(large?cfg.defaultContainer:'LCL'):x.load,containers=auto?Math.max(1,Math.ceil(+d.volume/cfg.referenceCbmPerLoad)):+x.containers,delivery=x.delivery||'transload',pallets=Math.ceil(+d.volume/cfg.cbmPerPallet),trucks=Math.max(1,Math.ceil(+d.volume/cfg.referenceCbmPerLoad));return{load,containers,delivery:load==='LCL'?'transload':delivery,pallets,trucks,large,auto}} 
function laNyLane(d,r){const prefix=Number(d.zip.slice(0,3));return r.id!=='ny'&&zone(d.zip)==='east'&&((prefix>=70&&prefix<=89)||(prefix>=100&&prefix<=149))}
function traditional(d,x){valid(d);const fobTotal=Math.round(Number(x.fobUnit)*Number(d.pieces)*100)/100;if(!['AUTO','LCL','20GP','40GP','40HQ','45HQ'].includes(x.load)||!Number.isFinite(+x.fobUnit)||+x.fobUnit<=0||!Number.isFinite(fobTotal)||fobTotal<=0||!Number.isInteger(+x.containers)||+x.containers<1)throw Error('Invalid trade details');if(x.delivery&&!['direct','transload'].includes(x.delivery))throw Error('Invalid delivery mode');if(x.broker==='own'&&(!Number.isFinite(+x.brokerFee)||+x.brokerFee<0))throw Error('Invalid broker fee');const taxSummary=root.TaxEngine.calculate(d,x),lp=loadPlan(d,x),cfg=root.FreightRules,z=zone(d.zip);return options(d).map(r=>{if(!Number.isFinite(r.lclPerCbm)||r.lclPerCbm<=0||!Number.isFinite(r.fclMultiplier)||r.fclMultiplier<=0)throw Error('Missing route freight rates');const cbm=r.lclPerCbm,container=({'20GP':2600,'40GP':3700,'40HQ':3900,'45HQ':4600})[lp.load],ocean=lp.load==='LCL'?Math.max(1,+d.volume)*cbm:container*r.fclMultiplier*lp.containers,port=lp.load==='LCL'?Math.max(95,+d.volume*28):480*lp.containers,broker=x.broker==='own'?+x.brokerFee:150,direct=lp.delivery==='direct',full=!direct&&lp.large,lane=!direct&&laNyLane(d,r)?cfg.laNy:null,unitRate=lane?Math.round((full?lane.ftlCost:lane.ltlCostPerPallet)*(1+lane.markup)*100)/100:direct?cfg.demoDrayageRates[z]:full?cfg.demoTruckRates[z]:cfg.demoPalletRates[z],units=direct?lp.containers:full?lp.trucks:lp.pallets,truck=unitRate*units,handling=lp.load!=='LCL'&&!direct?+d.volume*cfg.demoTransloadPerCbm:0,truckName=direct?['整柜直送（拖柜）','Container drayage']:full?['拆柜后整车派送','Truckload after transloading']:['按托派送','Pallet delivery'],rows=[['海运费','Ocean freight',ocean],['目的港费用','Destination port charges',port],['报关服务费'+(x.broker==='own'?'（客户自付）':''),'Broker fee'+(x.broker==='own'?' (paid separately)':''),broker],...(handling?[['拆柜及打托（示例）','Transloading & palletizing (demo)',handling]]:[]),[...truckName,truck],...taxSummary.rows.map(r=>r.slice(0,3))],total=rows.reduce((s,r)=>s+(r[2]??0),0);return{id:r.id,zh:r.zh,en:r.en,min:r.min,max:r.max,total,landed:total+fobTotal,per:(total+fobTotal)/d.pieces,fobTotal,taxSummary,complete:taxSummary.complete,rows,kind:'trade',oceanRate:cbm,loadPlan:lp,deliveryQuote:{lane:lane?'la-ny':null,mode:direct?'direct':full?'ftl':'pallet',units,unitRate,total:truck}}})}
function arrival(date,days){const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+days);return d.toISOString().slice(0,10)}
root.QuoteEngine={zone,valid,ecommerce,traditional,arrival,loadPlan};if(typeof module!=='undefined')module.exports=root.QuoteEngine;
})(globalThis);
